    slide.addShape(pptx.ShapeType.arc, { x:9.05, y:-0.95, w:4.9, h:4.9, adjustPoint:0.1, line:{color:C.cyan, transparency: 65, width:1.5}, fill:{color:C.navy, transparency:100} });
