  s.addText('Redefining Small and Efficient\nMultimodal Models', { x:0.7, y:2.02, w:5.75, h:1.12, fontFace:'Aptos Display', fontSize:27, bold:true, color:'EAF6FF', margin:0, breakLine:false, fit:'shrink' });
  s.addText('A compact VLM family from Hugging Face and Stanford that targets competitive multimodal performance with dramatically lower memory footprints.', { x:0.72, y:3.42, w:5.35, h:0.58, fontSize:13.2, color:'BFD0E4', margin:0, fit:'shrink' });
  card(s, 0.72, 4.35, 1.45, 0.94, {fill:'111B2D', line:'26364F', shadow:false}); stat(s,'256M','smallest model',0.9,4.48,1.05,C.cyan);
  card(s, 2.35, 4.35, 1.45, 0.94, {fill:'111B2D', line:'26364F', shadow:false}); stat(s,'0.8','GB RAM, b=1',2.55,4.48,1.0,C.teal);
  card(s, 3.98, 4.35, 1.45, 0.94, {fill:'111B2D', line:'26364F', shadow:false}); stat(s,'16K','max context',4.18,4.48,1.0,C.amber);
  s.addImage({ path: asset('figure_3.jpg'), x:6.65, y:1.38, w:5.95, h:2.5 });
  s.addShape(pptx.ShapeType.roundRect, { x:6.42, y:1.15, w:6.42, h:3.02, rectRadius:0.12, fill:{color:'FFFFFF', transparency:91}, line:{color:'5DD8FF', transparency:55, width:1.2} });
  const nodes = [['Image\nsplits',7.0,4.72,C.cyan],['SigLIP\nencoder',8.18,4.72,C.teal],['Pixel\nshuffle',9.36,4.72,C.purple],['SmolLM2\nbackbone',10.54,4.72,C.amber]];
  nodes.forEach(([t,x,y,c],i)=>{ s.addShape(pptx.ShapeType.roundRect,{x,y,w:0.93,h:0.62,rectRadius:0.08,fill:{color:c,transparency:10},line:{color:c}}); s.addText(t,{x:x+0.05,y:y+0.12,w:0.83,h:0.28,fontSize:8,bold:true,color:'FFFFFF',align:'center',margin:0,fit:'shrink'}); if(i<3) s.addShape(pptx.ShapeType.triangle,{x:x+0.98,y:y+0.19,w:0.22,h:0.22,rotate:90,fill:{color:'A6B7CE'},line:{color:'A6B7CE'}}); });
