  s.addText('SmolVLM frames compact multimodal modeling as a compute-allocation problem, not only a scaling problem.', {x:7.36,y:6.35,w:4.55,h:0.36,fontSize:10.5,color:'BFD0E4',margin:0,fit:'shrink'});
