  slide.addText(text, { x:x+0.12, y:y+0.078, w:w-0.24, h:0.16, fontSize:7.8, bold:true, color, margin:0, charSpacing:0.4, fit:'shrink' });
}
function card(slide, x,y,w,h, opts={}) {
  slide.addShape(pptx.ShapeType.roundRect, { x,y,w,h, rectRadius:0.1, fill:{color: opts.fill||C.card, transparency: opts.transparency||0}, line:{color: opts.line||'D9E2EC', transparency: opts.lineTrans||0, width: opts.lineW||1}, shadow: opts.shadow===false? undefined : {type:'outer', color:'64748B', opacity:0.13, blur:1.5, angle:45, distance:1} });
}
function stat(slide, num, label, x,y,w,color=C.teal, suffix='') {
  slide.addText(num, { x, y, w, h:0.55, fontSize:28, bold:true, color, margin:0, fit:'shrink' });
  if (suffix) slide.addText(suffix, { x:x+w-0.65, y:y+0.16, w:0.6, h:0.24, fontSize:11, bold:true, color, margin:0 });
  slide.addText(label, { x, y:y+0.58, w, h:0.32, fontSize:8.6, color:C.muted, margin:0, fit:'shrink' });
}
function addBullet(slide, lines, x, y, w, h, color=C.ink, size=12) {
  const runs = [];
  lines.forEach((line, i) => runs.push({ text: line, options: { bullet: { indent: 10 }, hanging: 3, breakLine: i < lines.length-1 } }));
  slide.addText(runs, { x, y, w, h, fontSize:size, color, margin:0.04, breakLine:false, fit:'shrink', paraSpaceAfterPt:4 });
}
function pill(slide, text, x,y,w, fill, color='FFFFFF') {
  slide.addShape(pptx.ShapeType.roundRect, { x,y,w,h:0.36, rectRadius:0.15, fill:{color:fill}, line:{color:fill} });
  slide.addText(text, { x:x+0.1, y:y+0.095, w:w-0.2, h:0.15, fontSize:7.5, color, bold:true, align:'center', margin:0, fit:'shrink' });
}
function arrow(slide, x,y,w,h,color=C.teal, width=2) {
  slide.addShape(pptx.ShapeType.chevron, { x, y, w, h, fill:{color, transparency:10}, line:{color, transparency:10} });
}

